struct ScaleKeyboard:juce::Component {
 SynthMavenProcessor&p;int target,selected=0,dragNote=-1;float initial=0;std::function<void(int)>onSelect;
 ScaleKeyboard(SynthMavenProcessor&proc,int t):p(proc),target(t){}
 int root()const{return juce::roundToInt(p.parameters.getRawParameterValue(p.tuningId(target,"root"))->load()*11);}
 int relative(int note)const{return (note-root()+12)%12;}
 std::array<juce::Rectangle<float>,12>rects()const{std::array<juce::Rectangle<float>,12>r;float w=getWidth()/7.f;int white[]={0,2,4,5,7,9,11};for(int n=0;n<7;n++)r[white[n]]={n*w,0,w,(float)getHeight()};int black[]={1,3,6,8,10},boundary[]={1,2,4,5,6};for(int n=0;n<5;n++)r[black[n]]={(boundary[n]-.31f)*w,0,w*.62f,getHeight()*.62f};return r;}
 int degree(int rel)const{unsigned mask=p.scaleMask(target);if(!(mask&(1u<<rel)))return 0;int d=0;for(int n=0;n<=rel;n++)if(mask&(1u<<n))d++;return d;}
 void paint(juce::Graphics&g)override{using namespace juce;auto r=rects();for(int pass=0;pass<2;pass++)for(int n=0;n<12;n++){bool black=MidiMessage::isMidiNoteBlack(n);if(black!=(pass==1))continue;int rel=relative(n),d=p.scaleDegree(target,60+n);double offset=p.tuningOffset(target,60+n);bool altered=std::abs(offset)>.5;Colour colour=altered?Colour(0xffee895d):d?Colour(0xff4caaa0):black?Colour(0xff17212d):Colour(0xffb4bdc8);g.setColour(colour);g.fillRoundedRectangle(r[n].reduced(1),5);g.setColour(rel==selected?Colours::white:Colour(0xff10151d));g.drawRoundedRectangle(r[n].reduced(1),5,rel==selected?2.5f:1);g.setColour(d||altered||black?Colours::white:Colour(0xff17212d));g.setFont(Font(black?16:21,Font::bold));auto area=r[n].toNearestInt();g.drawText(d?String(d):"-",area.withY(area.getY()+(black?24:130)).withHeight(28),Justification::centred);g.setFont(11);String name=MidiMessage::getMidiNoteName(60+n,true,false,4);g.drawText(name,area.withY(area.getBottom()-22).withHeight(18),Justification::centred);if(altered){g.setFont(Font(11,Font::bold));g.drawText(String(offset,1)+" ct",area.withY(area.getBottom()-44).withHeight(18),Justification::centred);}if(rel==0){g.setColour(Colour(0xffeffffb));g.fillEllipse(area.getCentreX()-3,area.getY()+12,6,6);}}}
 void mouseDown(const juce::MouseEvent&e)override{auto r=rects();dragNote=-1;for(int pass=1;pass>=0&&dragNote<0;pass--)for(int n=0;n<12;n++)if(juce::MidiMessage::isMidiNoteBlack(n)==(pass==1)&&r[n].contains(e.position)){selected=relative(n);dragNote=selected;break;}if(dragNote<0)return;if(onSelect)onSelect(selected);auto*q=p.parameters.getParameter(p.tuningId(target,"note"+juce::String(dragNote)));initial=q->getValue();q->beginChangeGesture();repaint();}
 void mouseDrag(const juce::MouseEvent&e)override{if(dragNote<0)return;p.parameters.getParameter(p.tuningId(target,"note"+juce::String(dragNote)))->setValueNotifyingHost(juce::jlimit(0.f,1.f,initial-e.getDistanceFromDragStartY()/400.f));repaint();}
 void mouseUp(const juce::MouseEvent&)override{if(dragNote>=0)p.parameters.getParameter(p.tuningId(target,"note"+juce::String(dragNote)))->endChangeGesture();dragNote=-1;}
};
